INSERT INTO cabinet_definitions (name, assembly_class, construction_method_id, default_dx, default_dy, default_dz,
  is_library_item, active, category_id, subcategory_id, top_type, toe_type, carcase_joints, material_overrides,
  hardware_overrides, toekick_overrides, drawerbox_overrides, exposed_interior, sort_order, no_cnc)
SELECT 'WOT', 'tall', construction_method_id, 636, 2100, 580, true, true, category_id, subcategory_id, top_type, toe_type,
  carcase_joints, '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, false, sort_order + 1, false
FROM cabinet_definitions WHERE name = 'UBO' AND NOT EXISTS (SELECT 1 FROM cabinet_definitions WHERE name = 'WOT');

