  part_comments = '{"custom_@0":"Edge in black","custom_@1":"Edge in black"}'::jsonb, kit = '{"members":[{"key":"lp","def":"TEPK","x":"0","dx":"t.exposed","dy":"tall.h","dz":"tall.d"},{"key":"dr","def":"D2-LL","x":"k.lp.w","dx":600,"dy":650,"dz":"tall.d","top_type":"full_top","neighbours":["cabinet","cabinet"]},{"key":"core","def":"self","x":"k.lp.w","y":"k.dr.h","dx":600,"dy":"600 + t.exposed + 380","dz":"tall.d","neighbours":["cabinet","cabinet"]},{"key":"up","def":"W2D","x":"k.lp.w","dx":600,"dz":400,"dy":"wallcab.top - k.core.top","gap":"tall.d - 400","rules":{"SCRBT":"t.exposed"},"parts":[{"visible":true,"show_in_room":true,"hide_views":[],"no_cnc":false,"material_override_id":null,"edge_top":false,"edge_bottom":false,"edge_left":false,"edge_right":false,"part_library_id":"0b364a0a-9018-4852-8ef5-172ab05dac32","name":"Under Panel","orientation":"flat","sort_order":0,"x":0,"y":0,"z":0,"dx":400,"dy":600,"dz":18,"expressions":{"dy":"cab.w","dx":"450 - t.door - 2","z":"cab.d + t.door + 2 - 450","dz":"t.exposed"}}],"neighbours":["cabinet","cabinet"]},{"key":"rp","def":"TEPK","x":"k.lp.w + 600","dx":"t.exposed","dy":"tall.h","dz":"tall.d"}]}'::jsonb,
